"""Generated bybit tax HTTP methods."""

from typing import Any

from .._market_http import MarketHTTP


class GeneratedTaxHTTP(MarketHTTP):
    """Tax API methods."""

    def create_tax_report_batch(
        self,
        *,
        start_time: int,
        end_time: int,
        items: list[Any],
        source_institution: str | None = None,
        export_file_type: str | None = None,
    ) -> dict[str, Any]:
        """
        Batch Request Export Reports. POST /v5/fht/compliance/tax/private/batch_create.

        Source: https://bybit-exchange.github.io/docs/v5/tax/batch-create

        Args:
            start_time: Report start, UNIX seconds
            end_time: Report end, UNIX seconds; at most 12 months after startTime
            items: Reports to export: objects with type and number
            source_institution: Identifier of the requesting institution
            export_file_type: orc (default) or csv
        """
        return self._native_private(
            "create_tax_report_batch",
            self._native_params(
                **{
                    "startTime": start_time,
                    "endTime": end_time,
                    "items": items,
                    "sourceInstitution": source_institution,
                    "exportFileType": export_file_type,
                }
            ),
        )

    def get_tax_report_batch(self, *, batch_id: str) -> dict[str, Any]:
        """
        Batch Query Export Reports. GET /v5/fht/compliance/tax/private/batch_query.

        Source: https://bybit-exchange.github.io/docs/v5/tax/batch-query

        Args:
            batch_id: Batch ID returned by batch_create
        """
        return self._native_private(
            "get_tax_report_batch", self._native_params(**{"batchId": batch_id})
        )

    def get_tax_register_time(self) -> dict[str, Any]:
        """
        Get User Register Date. POST /fht/compliance/tax/v3/private/registertime.

        Source: https://bybit-exchange.github.io/docs/v5/tax/register-time
        """
        return self._native_private("get_tax_register_time", [])
